mapper.update:
UPDATE medico SET numPersonal = #{numPersonal}, cedulaProfesional = #{cedulaProfesional}, nombreMedico = #{nombreMedico}, apellidosMedico = #{apellidosMedico}, fechaNacimiento = #{fechaNacimiento}, genero = #{genero}, email = #{email}, telefono = #{telefono}, domicilio = #{domicilio}, fotografia = #{fotografia}
, contrasena = #{contrasena}
, estatus = #{estatus}
WHERE idMedico = #{idMedico}

UPDATE medico
SET fotografia = #{fotografia}
WHERE idMedico = #{idMedico}

UPDATE medico
SET contrasena = #{contrasena}
WHERE idMedico = #{idMedico}

UPDATE medico
SET estatus = 'Inactivo'
WHERE idMedico = #{idMedico}

UPDATE cita c
INNER JOIN paciente p ON c.idPaciente = p.idPaciente
SET c.idMedicoAnterior = c.idMedico,
    c.idMedico = #{idMedicoDestino}
WHERE p.idMedico = #{idMedicoOrigen} AND c.idMedico = #{idMedicoOrigen}

UPDATE paciente
SET idMedico = #{idMedicoDestino}
WHERE idMedico = #{idMedicoOrigen}

mapper.select:
SELECT idMedico, numPersonal, cedulaProfesional, nombreMedico, apellidosMedico, fechaNacimiento, genero, email, telefono, domicilio, fotografia, estatus FROM medico
AND (nombreMedico LIKE CONCAT('%', #{nombre}, '%') OR apellidosMedico LIKE CONCAT('%', #{nombre}, '%'))
AND numPersonal = #{numPersonal}
AND cedulaProfesional LIKE CONCAT('%', #{cedulaProfesional}, '%')
AND estatus = #{estatus}
ORDER BY idMedico
